def days_after_start(year, month, day):
    """The game's calendar has no leap years; the 1936 bookmark starts on 1 January."""
    return (year - 1936) * 365 + sum(MONTHS[:month - 1]) + day - 1


def indent(text, tabs=1):
    pad = "\t" * tabs
    return "\n".join(pad + line if line else line for line in text.split("\n"))


def war(attacker, target):
    return f"{attacker} = {{\n\tdeclare_war_on = {{\n\t\ttarget = {target}\n\t\ttype = annex_everything\n\t}}\n}}"


def free_for_all(tags):
    lines = []
    for index, first in enumerate(tags):
        for second in tags[index + 1:]:
            lines.append(f"if = {{\n\tlimit = {{\n\t\t{first} = {{ exists = yes }}\n\t\t{second} = {{ exists = yes }}\n\t}}\n{indent(war(first, second))}\n}}")
    return "\n".join(lines)


def raise_army(tag, count, experience=0.2, rifles=None):
    """A template of plain infantry, its divisions and the rifles to arm them."""
    rifles = rifles if rifles is not None else count * 1000
    regiments = "\n".join(f"\t\t\tinfantry = {{ x = {x} y = {y} }}" for x in range(2) for y in range(4))
    return (f"{tag} = {{\n\tdivision_template = {{\n\t\tname = \"Army of {tag}\"\n\t\tregiments = {{\n{regiments}\n\t\t}}\n\t}}\n"
            f"\tadd_equipment_to_stockpile = {{\n\t\ttype = infantry_equipment\n\t\tamount = {rifles}\n\t}}\n"
            f"\tadd_manpower = {count * 12000}\n"
            f"\tfor_loop_effect = {{\n\t\tend = {count}\n\t\tcreate_unit = {{\n"
            f"\t\t\tdivision = \"division_template = \\\"Army of {tag}\\\" start_experience_factor = {experience}\"\n"
            f"\t\t\towner = {tag}\n\t\t}}\n\t}}\n}}")


def take(tag, states, owner):
    return "\n".join(f"if = {{\n\tlimit = {{ {s} = {{ is_owned_by = {owner} }} }}\n\t{tag} = {{ transfer_state = {s} }}\n}}" for s in states)


def rule(tag, party="neutrality", **popular):
    shares = {"neutrality": 70, "fascism": 10, "democratic": 10, "communism": 10}
    shares.update(popular)
    return (f"{tag} = {{\n\tset_politics = {{\n\t\truling_party = {party}\n\t\telections_allowed = no\n\t}}\n"
            "\tset_popularities = {\n" + "".join(f"\t\t{k} = {v}\n" for k, v in shares.items()) + "\t}\n}")


def lead(tag):
    # Recruited on day one in the country's history; an event can only promote.
    return f"{tag} = {{\n\tpromote_character = {LEADERS[tag][0]}\n}}"


def check_tables():
    final = dict(world.vanilla_states())
    for tag, states in world.TRANSFERS.items():
        for state in states:
            final[state] = tag
    import split_states
    for orig, parts in split_states.pieces().items():
        for new, _ in parts:
            final.setdefault(new, final.get(orig))
    held = sorted(s for s, owner in final.items() if owner in ("CHI", "KMT"))
    listed = sorted(s for states in CHINA.values() for s in states)
    if held != listed:
        raise SystemExit(f"China table is off: missing {sorted(set(held) - set(listed))}, extra {sorted(set(listed) - set(held))}")
    for states, owner in ((JAPAN_REBELS, "JAP"), (SPAIN_REBELS, "SPR"), (SPAIN_REPUBLIC, "SPR"), (AMERICA_REBELS, "USA")):
        for state in states:
            if final[state] != owner:
                raise SystemExit(f"state {state} is {final[state]}, not {owner}")
    for tag, (_, _, capital, states) in COLONIES.items():
        if capital not in states or any(final[s] != tag for s in states):
            raise SystemExit(f"colony table is off for {tag}")
    if sorted(world.SUBJECTS[1][2]) != sorted(SPANISH_SUBJECTS):
        raise SystemExit("colony list differs from build_world.SUBJECTS")


def write(path, text, encoding="utf-8"):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding=encoding)


def build_tags():
    write(MOD / "common" / "country_tags" / "lr_tags.txt", NOTE + "".join(f'{tag} = "countries/LR {row[0]}.txt"\n' for tag, row in NEW_TAGS.items()))
    recruits = {tag: LEADERS[tag][0] for tag in NEW_TAGS if tag in LEADERS}
    recruits["CNA"] = "USA_george_washington"
    for tag, (file, _, _, colour, capital, culture, _) in NEW_TAGS.items():
        write(MOD / "common" / "countries" / f"LR {file}.txt",
              f"graphical_culture = {culture}_gfx\ngraphical_culture_2d = {culture}_2d\n\ncolor = {{ {colour[0]} {colour[1]} {colour[2]} }}\n")
        write(MOD / "history" / "countries" / f"{tag} - {file}.txt",
              f"capital = {capital}\n\nrecruit_character = {recruits[tag]}\n\nset_technology = {{\n\tinfantry_weapons = 1\n}}\n\nset_politics = {{\n\truling_party = {'democratic' if tag == 'CNA' else 'neutrality'}\n\tlast_election = \"1936.1.1\"\n\telection_frequency = 48\n\telections_allowed = no\n}}\n"
              "set_popularities = {\n\tneutrality = 70\n\tfascism = 10\n\tdemocratic = 10\n\tcommunism = 10\n}\n")


def beiyang_flag():
    """The Five Races flag, until real art arrives."""
    colours = [(200, 40, 40), (240, 200, 60), (50, 90, 170), (240, 240, 240), (20, 20, 20)]
    image = Image.new("RGBA", (82, 52))
    for y in range(52):
        for x in range(82):
            image.putpixel((x, y), colours[y * 5 // 52] + (255,))
    return image


