def build_text():
    loc = ["l_korean:"]
    add = lambda key, value: loc.append(f' {key}:0 "{value}"')
    for key, (title, desc, label) in TEXT.items():
        add(f"{key}.t", title)
        add(f"{key}.d", LONG.get(f"{key}.d", desc))
        if label:
            add(f"{key}.a", label)
    for key, value in OPTION_LABELS.items():
        add(key, value)
    add("LR_FRA_volunteers_category", "내전 의용병")
    add("LR_FRA_volunteers_category_desc", f"다른 나라의 내전에 프랑스 의용 사단을 보냅니다. 사단 하나에 인력 8000과 소총 1000정이 들고, 한 나라에 최대 {VOLUNTEER_MAX}개 사단까지 보낼 수 있습니다. 그 나라와 프랑스가 서로 싸우고 있으면 보낼 수 없습니다.")
    for tag in VOLUNTEER_TARGETS:
        add(f"LR_dec_vol_{tag}", f"의용 사단 파견: [{tag}.GetName]")
        add(f"LR_dec_vol_{tag}_desc", f"[{tag}.GetName]에 프랑스 의용 사단 하나를 보냅니다. 인력 8000, 소총 1000정. 지금까지 보낸 사단 [?FRA.LR_vol_{tag}|0]/{VOLUNTEER_MAX}.")
    for number, (title, desc, reply) in GREAT_NEWS.items():
        add(f"lr_gnews.{number}.t", title)
        add(f"lr_gnews.{number}.d", desc)
        add(f"lr_gnews.{number}.a", reply)
    add("LR_balkan_pact", "발칸 조약")
    add("LR_imperial_league", "제국연맹")
    for key, name, *_ in LEADERS.values():
        add(key, name)
    for key, (_, name, *_) in LEADERS.items():
        pass
    write(MOD / "localisation" / "korean" / "lr_world_l_korean.yml", "\n".join(loc) + "\n", "utf-8-sig")

    names = ["l_korean:"]

    def named(tag, name, adjective, ideologies=("neutrality", "democratic", "fascism", "communism")):
        for suffix in ("", "_DEF"):
            names.append(f' {tag}{suffix}:0 "{name}"')
            names.extend(f' {tag}_{i}{suffix}:0 "{name}"' for i in ideologies)
        names.append(f' {tag}_ADJ:0 "{adjective}"')
        names.extend(f' {tag}_{i}_ADJ:0 "{adjective}"' for i in ideologies)

    for tag, row in NEW_TAGS.items():
        named(tag, row[1], row[2])
    for tag, (name, adjective) in RENAMED.items():
        named(tag, name, adjective)
    for key, (name, adjective, _) in COSMETICS.items():
        names.append(f' {key}:0 "{name}"')
        names.append(f' {key}_DEF:0 "{name}"')
        names.append(f' {key}_ADJ:0 "{adjective}"')
    for cosmetic, name, _ in FRANCE_UNDER.values():
        names.extend([f' {cosmetic}:0 "{name}"', f' {cosmetic}_DEF:0 "{name}"', f' {cosmetic}_ADJ:0 "프랑스"'])
    for tag, (region, _) in FRENCH_COLONIES_AFTER_DEFEAT.items():
        for suffix, name in (("red", f"{region} 사회주의 공화국"), ("free", f"{region} 공화국"), ("rk", f"{region} 국가판무관부")):
            names.extend([f' LR_{tag}_{suffix}:0 "{name}"', f' LR_{tag}_{suffix}_DEF:0 "{name}"', f' LR_{tag}_{suffix}_ADJ:0 "{region}"'])
    for tag, (name, adjective, _, _) in COLONIES.items():
        names.append(f' {tag}_democratic:0 "{name}"')
        names.append(f' {tag}_democratic_DEF:0 "{name}"')
        names.append(f' {tag}_democratic_ADJ:0 "{adjective}"')
    write(MOD / "localisation" / "korean" / "replace" / "lr_world_countries_l_korean.yml", "\n".join(names) + "\n", "utf-8-sig")


